// ARRAY-BACKED STACK — simple and cache-friendly
class ArrayStack {
    constructor() { this._data = []; }
    push(val)  { this._data.push(val); }           // O(1) amortized
    pop()      { return this._data.pop(); }         // O(1) amortized
    peek()     { return this._data[this._data.length - 1]; } // O(1)
    isEmpty()  { return this._data.length === 0; }  // O(1)
    get size() { return this._data.length; }         // O(1)
}

// LINKED LIST-BACKED STACK — guaranteed O(1), no resize ever
class ListNode {
    constructor(val, next = null) { this.val = val; this.next = next; }
}

class LinkedStack {
    constructor() { this._top = null; this._size = 0; }

    push(val) {
        this._top = new ListNode(val, this._top); // new node points to old top
        this._size++;
    }
    pop() {
        if (!this._top) return undefined;
        const val = this._top.val;
        this._top = this._top.next; // advance head to next node
        this._size--;
        return val;
    }
    peek()    { return this._top ? this._top.val : undefined; }
    isEmpty() { return this._top === null; }
    get size(){ return this._size; }
}

// VERIFY BOTH BEHAVE IDENTICALLY
function testStack(Stack) {
    const s = new Stack();
    s.push(1); s.push(2); s.push(3);
    console.log(s.peek());    // 3
    console.log(s.pop());     // 3
    console.log(s.pop());     // 2
    console.log(s.size);      // 1
    console.log(s.isEmpty()); // false
    s.pop();
    console.log(s.isEmpty()); // true
    console.log(s.pop());     // undefined — safe empty pop
}
