// VALID PARENTHESES — O(n) time, O(n) space
function isValid(s) {
    const stack = [];
    const pairs = { ')': '(', '}': '{', ']': '[' }; // closer -> expected opener

    for (const c of s) {
        if (c === '(' || c === '{' || c === '[') {
            stack.push(c);                   // opening: push
        } else {
            // closing: check stack top matches expected opener
            if (stack.length === 0 || stack[stack.length - 1] !== pairs[c]) {
                return false;                // empty stack OR wrong opener
            }
            stack.pop();                     // matched: consume opener
        }
    }
    return stack.length === 0;               // all openers must be consumed
}

