  const stack = [];
  const tagRe = /<\/?([a-z]+)>/g;
  let match;
  while ((match = tagRe.exec(html)) !== null) {
    const [full, tag] = match;
    if (!full.startsWith('</')) stack.push(tag);
    else if (stack.pop() !== tag) return false;
  }
  return stack.length === 0;
}

function validateCustomPairs(s, pairMap) {
  const openers = new Set(Object.values(pairMap));
  const closers = new Set(Object.keys(pairMap));
  const stack = [];
  for (const c of s) {
    if (openers.has(c)) {
      stack.push(c);
    } else if (closers.has(c)) {
      if (stack.length === 0 || stack[stack.length - 1] !== pairMap[c]) {
        return false;
      }
      stack.pop();
    }
    // else: ignore character
  }
  return stack.length === 0;
}

