// MIN STACK — O(1) for all operations including getMin
class MinStack {
    constructor() {
        this._stack = [];    // main stack
        this._minStack = []; // auxiliary: tracks min at every depth
    }

    push(val) {
        this._stack.push(val);
        // Push current min: either val (new minimum) or existing minimum
        const currentMin = this._minStack.length === 0
            ? val
            : Math.min(val, this._minStack[this._minStack.length - 1]);
        this._minStack.push(currentMin);
    }

    pop() {
        this._stack.pop();
        this._minStack.pop(); // always pop both together
    }

    top()    { return this._stack[this._stack.length - 1]; }
    getMin() { return this._minStack[this._minStack.length - 1]; } // O(1)
}

// TRACE: push(5), push(3), push(7), push(2), pop()
// push(5): stack=[5], minStack=[5]  (5 is min so far)
// push(3): stack=[5,3], minStack=[5,3]  (min(3,5)=3)
// push(7): stack=[5,3,7], minStack=[5,3,3]  (min(7,3)=3)
// push(2): stack=[5,3,7,2], minStack=[5,3,3,2]  (min(2,3)=2)
// getMin() -> minStack.top = 2  O(1)
// pop():  stack=[5,3,7], minStack=[5,3,3]
// getMin() -> minStack.top = 3  O(1) — correctly restored after pop

// OPTIMISED: only push to minStack when new element <= current min
// Saves space when many pushes are above the current minimum
class MinStackOptimised {
    constructor() { this._stack = []; this._minStack = []; }
    push(val) {
        this._stack.push(val);
        if (this._minStack.length === 0 ||
            val <= this._minStack[this._minStack.length - 1]) {
            this._minStack.push(val); // only push new min or equal
        }
    }
    pop() {
        const val = this._stack.pop();
        if (val === this._minStack[this._minStack.length - 1]) {
            this._minStack.pop(); // only pop from aux if it was a min
        }
    }
    getMin() { return this._minStack[this._minStack.length - 1]; }
}

