// EFFICIENT QUEUE using head pointer — O(1) dequeue
class Queue {
    constructor() {
        this._data = {};
        this._head = 0;
        this._tail = 0;
    }
    enqueue(val) {
        this._data[this._tail] = val; // add at tail index
        this._tail++;                  // advance tail
    }
    dequeue() {
        if (this.isEmpty()) return undefined;
        const val = this._data[this._head];
        delete this._data[this._head]; // free memory
        this._head++;                  // advance head — O(1), no shifting
        return val;
    }
    front()    { return this._data[this._head]; }
    isEmpty()  { return this._head === this._tail; }
    get size() { return this._tail - this._head; }
}

