// QUEUE USING TWO STACKS — amortized O(1)
class MyQueue {
    constructor() {
        this._in  = []; // new elements pushed here
        this._out = []; // elements popped from here
    }

    push(val) {
        this._in.push(val); // always enqueue to inStack O(1)
    }

    pop() {
        this._transfer(); // ensure outStack has elements
        return this._out.pop(); // O(1) from outStack
    }

    peek() {
        this._transfer();
        return this._out[this._out.length - 1];
    }

    empty() { return this._in.length === 0 && this._out.length === 0; }

    _transfer() {
        // Only transfer when outStack is empty — lazy evaluation
        if (this._out.length === 0) {
            while (this._in.length > 0) {
                this._out.push(this._in.pop()); // reverse order -> FIFO
            }
        }
    }
}

