// CIRCULAR BUFFER QUEUE — fixed capacity, O(1) guaranteed
class CircularQueue {
    constructor(capacity) {
        this._buf  = new Array(capacity);
        this._cap  = capacity;
        this._head = 0;
        this._size = 0;
    }
    get _tail() { return (this._head + this._size) % this._cap; }

    enqueue(val) {
        if (this._size === this._cap) throw new Error('Queue full');
        this._buf[this._tail] = val;
        this._size++;
    }
    dequeue() {
        if (this._size === 0) throw new Error('Queue empty');
        const val = this._buf[this._head];
        this._head = (this._head + 1) % this._cap; // wrap around
        this._size--;
        return val;
    }
    get size() { return this._size; }
}

