// NEXT GREATER ELEMENT I — O(n) monotonic decreasing stack
function nextGreaterElement(nums) {
    const result = new Array(nums.length).fill(-1); // default: no greater element
    const stack = []; // stores INDICES of elements awaiting their answer

    for (let i = 0; i < nums.length; i++) {
        // Pop all elements smaller than current — current is their next greater
        while (stack.length > 0 && nums[stack[stack.length - 1]] < nums[i]) {
            const idx = stack.pop();
            result[idx] = nums[i]; // nums[i] is the next greater for nums[idx]
        }
        stack.push(i); // push current index — awaiting its next greater
    }
    // Remaining in stack: no greater element exists -> result stays -1
    return result;
}

