// LARGEST RECTANGLE IN HISTOGRAM — O(n) monotonic increasing stack
function largestRectangleArea(heights) {
    // Append 0 sentinel: forces all remaining bars to pop at the end
    heights = [...heights, 0];
    const stack = []; // monotonic increasing stack of indices
    let maxArea = 0;

    for (let i = 0; i < heights.length; i++) {
        // Pop all bars taller than current — they cannot extend right
        while (stack.length > 0 && heights[stack[stack.length - 1]] >= heights[i]) {
            const height = heights[stack.pop()];       // height of the popped bar
            // Width: from (new stack top + 1) to (i - 1)
            const width = stack.length === 0
                ? i                                    // extends from index 0 to i-1
                : i - stack[stack.length - 1] - 1;    // bounded on left by new stack top
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i); // push current index
    }
    return maxArea;
}

