function classifyStructure(signals) {
  const s = new Set(signals);
  if (s.has('nested') || s.has('matching') || s.has('undo') || s.has('dfs')) return 'Stack';
  if (s.has('level_order') || s.has('bfs') || s.has('fifo')) return 'Queue';
  if (s.has('next_greater') || s.has('span') || s.has('histogram')) return 'Monotonic Stack';
  return 'Unknown';
}

function solveStackProblem(s) {
  const stack = [];
  const pairs = { ')': '(', '}': '{', ']': '[' };
  for (const c of s) {
    if (c === '(' || c === '{' || c === '[') stack.push(c);
    else {
      if (stack.length === 0 || stack[stack.length - 1] !== pairs[c]) return false;
      stack.pop();
    }
  }
  return stack.length === 0;
}

function solveQueueProblem(operations) {
  const inStack = [];
  let outStack = [];
  const results = [];
  function transfer() {
    if (outStack.length === 0) {
      while (inStack.length > 0) outStack.push(inStack.pop());
    }
  }
  for (const o of operations) {
    if (o.op === 'enqueue') inStack.push(o.val);
    else if (o.op === 'dequeue') {
      transfer();
      results.push(outStack.pop());
    }
  }
  return results;
}

function solveMonotonicProblem(nums) {
  const result = new Array(nums.length).fill(-1);
  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length > 0 && nums[stack[stack.length - 1]] < nums[i]) {
      const idx = stack.pop();
      result[idx] = nums[i];
    }
    stack.push(i);
  }
  return result;
}

function moduleCapabilitySummary() {
  return {
    stack: solveStackProblem('()') === true,
    queue: Array.isArray(solveQueueProblem([{op:'enqueue',val:1},{op:'dequeue'}])),
    monotonicStack: Array.isArray(solveMonotonicProblem([1,2]))
  };
}
